from ...templatesession import new_session
from ...exception import InvalidCertificateType, MismatchIssuerAndSerialNumber
from .base_trs_cli import BaseTRSCLIInterface
from collections import OrderedDict


class CertificateInterface(BaseTRSCLIInterface):

    def add_certificate(self, certificate_file=None, certificate_password=None, timeout='5min', **kwargs):
        """Adds certificate file to the BTSSM to enable IPSec through the TRS commandline tools.

        :param string  certificate_file:      Path to certificate file.
        :param string  certificate_password:  Certificate password.

        :return: The UNIX status return message after executing the add certificate java command.
        :rtype: string

        :raises: BTSSMExecutionError: Raised when an UNIX error message is returned after
                 executing the added java command as well as other internal system errors.
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        config = self.command_store.get(alias).get_config()
        timeout = self._convert_to_secs(timeout)
        params = OrderedDict([('installBtsCertChain', certificate_file), ('btsPkcs12Password', certificate_password),
                             ('ne', kwargs.get('ne', config.trs_ip).strip()), ('pw', kwargs.get('pw', config.pw).strip())])
        with new_session.NewSession(alias, config, timeout=timeout) as session:
            add_certificate_command = session.cmd_builder.trs_tool.build(params=params)
            session.executor.run_via_shell(cmd=add_certificate_command, op='installBtsCertChain')
            status_message = session.executor.run_via_shell(cmd=CertificateInterface.READ_LOG_FILE_CMD, op='installBtsCertChain')
            self._check_for_errors(status_message)
            return status_message

    def add_bts_ta_certificate(self, ta_cert_file, ta_pkcs12_password, timeout='5min', **kwargs):
        """Adds BTS TA certificate to SEM.

        NOTE: ta_pkcs12_password should have the same index as their corresponding ta_cert_file

        :param list ta_cert_file:        List of certificate files
        :param list ta_pkcs12_password:  List of PKCS12 passwords

        :return: The UNIX status return message after executing the add certificate java command.
        :rtype: string

        :raises: BTSSMExecutionError: Raised when an UNIX error message is returned after
                 executing the added java command as well as other internal system errors.
        :raises: MismatchIssuerAndSerialNumber: Raised when certificate list length is not identical to
                 password list length
        """

        if len(ta_cert_file) != len(ta_pkcs12_password):
            raise MismatchIssuerAndSerialNumber('Please check list of ta_cert_file and ta_pkcs12_password\n{}\n{}'.format(ta_cert_file,
                                                                                                                          ta_pkcs12_password))
        self._execute_add_certificate(cert_file=ta_cert_file, cert_type='taCertFile',
                                      timeout=timeout, ta_pkcs12_password=ta_pkcs12_password, **kwargs)

    def add_802x_certificate(self, certificates, timeout='5min', **kwargs):
        """Adds 802.1X certificate to SEM.

        :param list certificates:        List of 802.1X certificate files

        :return: The UNIX status return message after executing the add certificate java command.
        :rtype: string

        :raises: BTSSMExecutionError: Raised when an UNIX error message is returned after
                 executing the added java command as well as other internal system errors.
        """
        self._execute_add_certificate(cert_file=certificates, cert_type='x802CertFile',
                                      timeout=timeout, **kwargs)

    def _execute_add_certificate(self, cert_file, cert_type, timeout, ta_pkcs12_password=None, **kwargs):
        cert_operations = {'x802CertFile': 'add802XCert', 'taCertFile': 'addBtsTaCert'}
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        config = self.command_store.get(alias).get_config()
        timeout = self._convert_to_secs(timeout)
        params = OrderedDict([('ne', kwargs.get('ne', config.trs_ip).strip()), ('pw', kwargs.get('pw', config.pw).strip())])
        operation = cert_operations[cert_type]
        with new_session.NewSession(alias, config, timeout=timeout) as session:
            cert_file.append(cert_type)
            if cert_type is 'taCertFile':
                ta_pkcs12_password.append('taPkcs12Password')
                zip_params = list(zip(cert_file, ta_pkcs12_password))
            else:
                zip_params = list(zip(cert_file))
            add_certificate_command = session.cmd_builder.trs_tool.build(op=operation, zip_params=zip_params, params=params)
            session.executor.run_via_shell(cmd=add_certificate_command, op=operation)
            status_message = session.executor.run_via_shell(cmd=CertificateInterface.READ_LOG_FILE_CMD, op=operation)
            self._check_for_errors(status_message)
            return status_message

    def delete_bts_ta_certificate(self, issuers, serial_nos, timeout='5min', **kwargs):
        """Deletes BTS TA certificate added to SEM

        NOTE: serial numbers should have the same index as their corresponding issuer

        :param list issuers:         List of issuers
        :param list serial_nos:      List of serial numbers

        :return: The UNIX status return message after executing the delete certificate java command.
        :rtype: string

        :raises: BTSSMExecutionError: Raised when an UNIX error message is returned after
                 executing the added java command as well as other internal system errors.
        :raises: MismatchIssuerAndSerialNumber: Raised when issuer list length is not identical
                 to serial number list length.
        """
        self._execute_delete_certificate(issuers=issuers, serial_nos=serial_nos, op='deleteBtsTaCert', timeout=timeout, **kwargs)

    def delete_802x_certificate(self, issuers, serial_nos, timeout='5min', **kwargs):
        """Deletes 802.1X certificate added to SEM

        NOTE: serial numbers should have the same index as their corresponding issuer

        :param list issuers:         List of issuers
        :param list serial_nos:      List of serial numbers

        :return: The UNIX status return message after executing the delete certificate java command.
        :rtype: string

        :raises: BTSSMExecutionError: Raised when an UNIX error message is returned after
                 executing the added java command as well as other internal system errors.
        :raises: MismatchIssuerAndSerialNumber: Raised when issuer list length is not identical
                 to serial number list length.
        """
        self._execute_delete_certificate(issuers=issuers, serial_nos=serial_nos, op='delete802XCert', timeout=timeout, **kwargs)

    def _execute_delete_certificate(self, issuers, serial_nos, op, timeout, **kwargs):
        if len(issuers) != len(serial_nos):
            raise MismatchIssuerAndSerialNumber('Please check list of issuers and serial_nos\n{}\n{}'.format(issuers, serial_nos))

        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        config = self.command_store.get(alias).get_config()
        timeout = self._convert_to_secs(timeout)
        params = OrderedDict([('ne', kwargs.get('ne', config.trs_ip).strip()), ('pw', kwargs.get('pw', config.pw).strip())])
        with new_session.NewSession(alias, config, timeout=timeout) as session:
            issuers.append('issuer')
            serial_nos.append('serialNo')
            delete_certificate_command = session.cmd_builder.trs_tool.build(op=op, zip_params=list(zip(issuers, serial_nos)), params=params)
            session.executor.run_via_shell(cmd=delete_certificate_command, op=op)
            status_message = session.executor.run_via_shell(cmd=CertificateInterface.READ_LOG_FILE_CMD, op=op)
            self._check_for_errors(status_message)
            return status_message

    def fetch_certificates(self, output_directory, output_format=None, timeout='5min', **kwargs):
        """Fetch all installed certificates

        :param string output_directory:     output directory
        :param string output_format:        output format. only zip format is supported

        ::
            Fetch Certificates      output_directory=certificates

            OUPUT:
            certificates/

            Fetch Certificates      output_directory=certificates   output_format=zip

            OUTPUT:
            certificates.zip

        :raises: BTSSMExecutionError: Raised when an UNIX error message is returned after
                 executing the added java command as well as other internal system errors.

        *******
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        config = self.command_store.get(alias).get_config()
        timeout = self._convert_to_secs(timeout)
        if output_format:
            params = OrderedDict([('fetchCerts', output_directory), ('outputFormat', output_format)])
        else:
            params = OrderedDict([('fetchCerts', output_directory)])
        params['ne'] = kwargs.get('ne', config.trs_ip).strip()
        params['pw'] = kwargs.get('pw', config.pw).strip()
        with new_session.NewSession(alias, config, timeout=timeout) as session:
            fetch_certificates_command = session.cmd_builder.trs_tool.build(params=params)
            self._log.info(fetch_certificates_command)
            session.executor.run_via_shell(cmd=fetch_certificates_command, op='fetchCerts')
            status_message = session.executor.run_via_shell(cmd=CertificateInterface.READ_LOG_FILE_CMD, op='fetchCerts')
            self._check_for_errors(status_message)
            return status_message

    def display_certificates(self, cert_type='all', timeout='5min', **kwargs):
        """Displays certificates installed

        :param string cert_type:     Type of certificate to display. Defaults to all

        :raises: BTSSMExecutionError: Raised when an UNIX error message is returned after
                 executing the added java command as well as other internal system errors.
        :raises: InvalidCertificateType: Raised when cert_type provided is invalid.
                 Supported certificate types: btsCertChain, raCertChain, otherTrustAnchors, vendorCertChain, x802Cert, all
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        config = self.command_store.get(alias).get_config()
        timeout = self._convert_to_secs(timeout)

        if cert_type not in ('btsCertChain', 'raCertChain', 'otherTrustAnchors', 'vendorCertChain', 'x802Cert', 'all'):
            raise InvalidCertificateType('{} is not a valid certificate.'.format(cert_type))

        params = OrderedDict([('displayCerts', cert_type),
                             ('ne', kwargs.get('ne', config.trs_ip).strip()), ('pw', kwargs.get('pw', config.pw).strip())])
        with new_session.NewSession(alias, config, timeout=timeout) as session:
            display_certificates_command = session.cmd_builder.trs_tool.build(params=params)
            output = session.executor.run_via_shell(cmd=display_certificates_command, op='displayCerts')
            status_message = session.executor.run_via_shell(cmd=CertificateInterface.READ_LOG_FILE_CMD, op='displayCerts')
            self._check_for_errors(status_message)
            return output, status_message

